syntax:
void *ptr; // Pointer declaration
ptr = NULL; // Initialize pointer to null
// Assign valid memory
ptr = malloc(size);
// Check validity before dereferencing
if (ptr != NULL) {
    // safe to dereference
}
// After freeing memory
free(ptr);
ptr = NULL; // Reset pointer to avoid dangling reference

code_example:
int *p = malloc(sizeof(int));
if (p == NULL) {
    // handle allocation failure
}
*p = 42; // Use pointer safely after allocation
free(p);
p = NULL; // Reset pointer to prevent dangling reference
// Later in code
if (p != NULL) {
    *p = 100; // Unsafe if p is dangling
}
